import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DgVVaeR-.js";const y=JSON.parse('{"title":"PallaSync 同期エンジン仕様","description":"","frontmatter":{"title":"PallaSync 同期エンジン仕様"},"headers":[],"relativePath":"dev/pallasync-engine.md","filePath":"dev/pallasync-engine.md","lastUpdated":1791013521000}'),d={name:"dev/pallasync-engine.md"};function n(l,e,c,i,s,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="pallasync-同期エンジン仕様" tabindex="-1">PallaSync 同期エンジン仕様 <a class="header-anchor" href="#pallasync-同期エンジン仕様" aria-label="Permalink to &quot;PallaSync 同期エンジン仕様&quot;">​</a></h1><h2 id="対象データとプロトコル" tabindex="-1">対象データとプロトコル <a class="header-anchor" href="#対象データとプロトコル" aria-label="Permalink to &quot;対象データとプロトコル&quot;">​</a></h2><p><code>PallaSyncSettingsEvents.kt</code> が生成する対象は、お気に入りタグ、検索履歴、タグ・ユーザー・作品ミュート、既読フィード作品、閲覧履歴です。テーマや認証トークン、保存画像を含むAppSettings全体を複製する実装ではありません。</p><p><code>PallaSyncWireModels.kt</code> の現行プロトコルは <strong>2.1</strong>、旧版 <strong>2.0</strong> も受け付けます。受信ページサイズは200件です。イベントにはスキーマ、エンティティID、<code>upsert</code> / <code>delete</code> 操作を持たせます。</p><h2 id="責務" tabindex="-1">責務 <a class="header-anchor" href="#責務" aria-label="Permalink to &quot;責務&quot;">​</a></h2><table tabindex="0"><thead><tr><th>実装</th><th>役割</th></tr></thead><tbody><tr><td><code>PalleriaSyncManager</code> / <code>PalleriaSyncCoordinator</code></td><td>チェーン作成・参加、復旧、同期要求、送受信の実行</td></tr><tr><td><code>PallaSyncSettingsEvents</code> / <code>PallaSyncEventWriter</code></td><td>ローカル差分からイベントを生成し送信キューへ保存</td></tr><tr><td><code>PallaSyncEventApplier</code></td><td>受信イベントを設定・コレクションへ適用</td></tr><tr><td><code>PallaSyncConflictResolver</code></td><td>バージョンベクトルと決定的な順序比較</td></tr><tr><td><code>PallaSyncKeystore</code></td><td>チェーンの鍵素材をEncryptedSharedPreferencesへ保存</td></tr><tr><td><code>rust/pallasync-core</code></td><td>レコードの暗号化・復号・署名検証など。AndroidからJNIで利用</td></tr></tbody></table><h2 id="暗号化の区別" tabindex="-1">暗号化の区別 <a class="header-anchor" href="#暗号化の区別" aria-label="Permalink to &quot;暗号化の区別&quot;">​</a></h2><p>通信レコードの2.1形式は <strong>XChaCha20-Poly1305</strong> を使い、24バイトのnonceを扱います。復号側は旧2.0のChaCha20-Poly1305形式も処理します。署名にはEd25519を使用します。</p><p>Android側の鍵保存に使うAES256-GCM / AES256-SIV（EncryptedSharedPreferences）と、通信本文の暗号方式は別です。同期サーバーへ送る本文は暗号化しますが、チェーンIDや配送・順序制御の情報をすべて隠す設計ではありません。</p><h2 id="競合と耐久性" tabindex="-1">競合と耐久性 <a class="header-anchor" href="#競合と耐久性" aria-label="Permalink to &quot;競合と耐久性&quot;">​</a></h2><p><code>compareVectors</code> は端末ごとのカウンターで因果関係を比較します。同時更新の比較は <strong><code>(lamport, deviceId, deviceSeq)</code></strong> の順序で行います。端末の壁時計の時刻だけで勝敗を決める方式ではありません。</p><p>Roomにはoutbox、チェーン状態、端末、inboxを保存します。relay cursorとLamport clockを保持し、受信データをinboxへ耐久保存してから適用します。復号・検証・スキーマ処理に失敗した受信項目は隔離します。初回pull完了前の変更は <code>pending_initial_merge</code> として待機します。</p><p>実装: <a href="https://github.com/yunfie-twitter/Palleria/tree/main/app/src/main/java/com/yunfie/illustia/pallasync" target="_blank" rel="noreferrer">同期パッケージ</a>、<a href="https://github.com/yunfie-twitter/Palleria/blob/main/rust/pallasync-core/src/crypto.rs" target="_blank" rel="noreferrer">Rust暗号処理</a>。</p>',13)])])}const u=a(d,[["render",n]]);export{y as __pageData,u as default};
